-- organelle: format-comparison
-- membrane: shared-substrate
-- channel: ← meta-manifest
-- purpose: Core concept comparison between agentskills and our skill format

INSERT OR IGNORE INTO fundamentals (id, investigation_id, title, description, our_equivalent, verdict) VALUES
  ('FUND.VALUE.PROPS', 'MANIFEST.AGENTSKILLS.SPEC.EVALUATION', 'Value Propositions',
   'Format claims 3 values: domain expertise (packaging specialized knowledge), repeatable workflows (consistent multi-step procedures), cross-product reuse (one skill works across 40+ tools). Originally developed by Anthropic as open standard.',
   'Domain expertise and workflows delivered via skill format. Cross-product reuse inapplicable — format is project-specific.',
   'agentskills superior for cross-product reuse; our format equal on domain expertise and workflows'),
  ('FUND.SPEC', 'MANIFEST.AGENTSKILLS.SPEC.EVALUATION', 'Specification',
   'Minimal frontmatter: name+description required. Body has zero format restrictions. Optional: license, compatibility, metadata, allowed-tools. Dir: SKILL.md + optional scripts/, references/, assets/.',
   'Extended frontmatter: adds state-profile. Rigid body sections. Flat skill dir — no scripts/, references/, assets/.',
   'agentskills superior for flexibility and dir structure; our format superior for state-awareness'),
  ('FUND.ASSETS', 'MANIFEST.AGENTSKILLS.SPEC.EVALUATION', 'Assets Directory',
   'Optional assets/ directory for templates, images, data files. Loaded on demand via progressive disclosure.',
   'No equivalent — all content lives in SKILL.md or is absent.',
   'agentskills superior — enables progressive loading of static resources'),
  ('FUND.DESC.PRINCIPLES', 'MANIFEST.AGENTSKILLS.SPEC.EVALUATION', 'Description — Writing Principles',
   '4 principles: imperative phrasing ("Use this skill when..." not "This skill does..."); focus on user intent not implementation; err on pushy side (list contexts even without explicit domain mention); keep concise (hard 1024-char limit).',
   'Static descriptions, no systematic writing principles applied.',
   'agentskills clearly superior — our descriptions are static and untested'),
  ('FUND.DESCRIPTION', 'MANIFEST.AGENTSKILLS.SPEC.EVALUATION', 'Description — Trigger Eval Loop',
   '20 queries (8-10 should-trigger, 8-10 should-not). Vary phrasing/explicitness/detail/complexity. Near-misses for should-not. 3 runs per query, trigger rate threshold 0.5. Train/validation ~60/40 split, proportional mix, fixed across iterations. Loop: evaluate both → identify train failures → revise (narrow/broaden/generalize/restructure) → repeat ≤5 iterations. Select best by validation pass rate. Skill-creator Skill automates.',
   'Static description, no trigger testing or optimization.',
   'agentskills clearly superior — no testing, no iteration'),
  ('FUND.EVAL.WORKSPACE', 'MANIFEST.AGENTSKILLS.SPEC.EVALUATION', 'Eval — Workspace Structure',
   'Workspace per iteration: iteration-N/eval-name/with_skill|without_skill/outputs/ + timing.json + grading.json. Benchmark.json with with/without/delta pass_rate/time/tokens (mean+stddev). evals.json as test case manifest. Clean context per run.',
   'No eval workspace or structured output capture.',
   'agentskills clearly superior'),
  ('FUND.EVALS', 'MANIFEST.AGENTSKILLS.SPEC.EVALUATION', 'Eval — Assertions + Grading',
   'Assertions: verifiable pass/fail checks, added after first run. Concrete evidence required (quote/reference). grading.json: assertion_results[] with text/passed/evidence + summary. Blind LLM comparison for holistic quality. Benchmark delta tells cost vs benefit.',
   'No assertion framework or grading methodology.',
   'agentskills clearly superior'),
  ('FUND.EVAL.PATTERNS', 'MANIFEST.AGENTSKILLS.SPEC.EVALUATION', 'Eval — Pattern Analysis',
   '5 analysis patterns: remove always-pass assertions (inflate rate), investigate always-fail (broken assertion or too hard), study pass-with-skill (where skill adds value), tighten inconsistent runs (high stddev → ambiguous instructions), check time/token outliers (read execution transcript for bottleneck).',
   'No pattern analysis on eval results.',
   'agentskills clearly superior'),
  ('FUND.EVAL.HUMAN', 'MANIFEST.AGENTSKILLS.SPEC.EVALUATION', 'Eval — Human Review + Iteration',
   'feedback.json with specific actionable feedback per eval ("chart missing axis labels" not "looks bad"). 5-step iteration: signal→LLM→revise→rerun→grade→review. Guidelines: generalize, keep lean, explain why, bundle repeated work. Stop when satisfied or plateau.',
   'No human review or iteration methodology.',
   'agentskills clearly superior'),
  ('FUND.SCRIPTS', 'MANIFEST.AGENTSKILLS.SPEC.EVALUATION', 'Script Patterns',
   'Self-contained scripts with inline deps: PEP 723 (Python/uv run), Deno npm: (TypeScript), Bun (TypeScript), bundler/inline (Ruby). --help, no interactive prompts, helpful errors, structured delimited output (JSON), stdout/stderr separation, predictable size handling (summary default, --offset/--output), version pinning, compatibility field, complex→script migration, idempotency, dry-run, meaningful exit codes, safe defaults.',
   'Bun+TypeScript inline-deps matches. Gaps: Ruby not used, no predictable size handling, no compatibility field.',
   'Strong alignment — small gaps on size handling and compatibility'),
  ('FUND.PROGRESSIVE', 'MANIFEST.AGENTSKILLS.SPEC.EVALUATION', 'Progressive Disclosure',
   'Metadata (~100 tokens) at startup for all skills. SKILL.md body loaded on activation. References/scripts/assets loaded on demand.',
   'Full SKILL.md loaded when skill activates. No references/ directory. No progressive loading.',
   'agentskills superior for context management'),
  ('FUND.BP.PATTERNS', 'MANIFEST.AGENTSKILLS.SPEC.EVALUATION', 'Best Practices — Instruction Patterns',
   '6 recommended patterns: gotchas (concrete error corrections), templates (pattern-matching for output), checklists (multi-step tracking), validation loops (self-correct before proceeding), plan-validate-execute (batch/destructive ops with intermediate plan), bundling scripts (reusable logic).',
   'Only gotchas section and script bundling adopted. Missing: templates, checklists, validation loops, plan-validate-execute.',
   'agentskills superior — we lack 4 of 6 patterns'),
  ('FUND.BP.SOURCES', 'MANIFEST.AGENTSKILLS.SPEC.EVALUATION', 'Best Practices — Source Material for Synthesis',
   '5 artifact types for synthesizing skills: internal docs/runbooks/style guides, API specs/schemas/configs, code review comments/issue trackers, version control history (patches/fixes), real-world failure cases.',
   'Skills created from scratch or from task extraction. No documented synthesis pipeline from project artifacts.',
   'agentskills superior — concrete artifact list we lack'),
  ('FUND.BP.REFINEMENT', 'MANIFEST.AGENTSKILLS.SPEC.EVALUATION', 'Best Practices — Real-Execution Refinement',
   'Run skill against real tasks. Read execution traces, not just final outputs. Three root causes of wasted agent time: instructions too vague (multiple approaches tried), instructions not applicable (agent follows anyway), too many options without clear default. Feed all results back into SKILL.md.',
   'Skills created once, rarely revised. No systematic trace-analysis feedback loop.',
   'agentskills superior — no refinement loop, no trace diagnosis'),
  ('FUND.SECTIONS', 'MANIFEST.AGENTSKILLS.SPEC.EVALUATION', 'Section Enforcement',
   'No required sections. Body is free-form. Best practices recommendation separate from spec.',
   'Trigger/Procedure/Rules/Gotchas enforced by audit-skills. Violations fail audit even for reference-only skills.',
   'Neither optimal — need tiered enforcement');
